	virtual void JavaIdle();		virtual void* SetupPortRequest();		virtual void RestorePortRequest(void* refCon);		virtual bool ResizeRequest(CRect_AC& desiredRect);		virtual void ShowHideRequest(bool showIt);		virtual void CheckUpdateRequest();		virtual void InvalRectRequest(const CRect_AC& invalidRect);		//#pragma message ("UJavaView.h: Implement JavaAdjustVisibility.")	virtual void JavaAdjustVisibility() const { };};//----------------------------------------------------------------------------------------// TJavaURLView//----------------------------------------------------------------------------------------class EXPORT_MA TJavaURLView : public TJavaView// This view is designed to stream in a URL from a view resource{	MA_DECLARE_CLASS;	public:	TJavaURLView(ResNumber urlStrListID = kNoResource_AC, short urlIndex = 0, 				 ResNumber appletCodeStrListID = kNoResource_AC, short appletCodeIndex = 0,				 const CViewRect& itsFrame = gZeroRect,				 SizeDeterminer itsHSizeDet = sizeVariable, SizeDeterminer itsVSizeDet = sizeVariable);		virtual ~TJavaURLView();		// Streaming		virtual void ReadFields(CStream_AC* aStream);		virtual void WriteFields(CStream_AC* aStream) const;		virtual void DoPostCreate(TDocument* itsDocument);		// New API		virtual CJavaAppletContainer_AC* DoMakeJavaAppletContainer(const CTempJavaAppletLocator_AC& tempLocator);		// create an applet container, given fURL and frameprotected:	ResNumber	fURLStrListID;						// url:	STR# rsrc id	short		fURLIndex;							// index into STR#	ResNumber	fAppletCodeStrListID;				// applet code:	STR# rsrc id	short		fAppletCodeIndex;					// index into STR#};//----------------------------------------------------------------------------------------EXPORT_MA void InitUJavaView();//----------------------------------------------------------------------------------------#endif